Method.Implementation:
	set stat = $$$OK

 	set data.fstNm = $ZCONVERT($ZSTRIP(data.fstNm,  "<>WC"), "U")
 	set data.midNm = $ZCONVERT($ZSTRIP(data.midNm,  "<>WC"), "U")
 	set data.lstNm = $ZCONVERT($ZSTRIP(data.lstNm,  "<>WC"), "U")
 	if ($L(data.midNm) > 0)
 	{
 		set data.fullNm = data.fstNm _ " " _ data.midNm   _ " " _ data.lstNm
 	}
 	else
 	{
	 	set data.fullNm = data.fstNm _ " " _ data.lstNm
 	}
 	$$$TRACE("Full name: " _ data.fullNm)
 	set data.titleNm = $ZCONVERT($ZSTRIP(data.titleNm,  "<>WC"), "U")
 	// CORPPRV
 	if ( (data.sourceSystem = "CORPPRV") && ($FIND(data.titleNm, ",") > 0) )
 	{
	 	set temp = data.titleNm
	 	set data.titleNm = $Piece(temp,",")
	 	set data.degree = $Piece(temp,",",2)
 	}
 	if ($L(data.titleNm) > 0)
 	{
 		set data.fullNm = data.fullNm _ "," _ data.titleNm
 	}
    Quit stat
